//! Files nobody reviews by hand: lockfiles and generated code. The review filter leaves them out
//! unless it is told to review them (SPEC §4.6).

/// Globs of the file names, at any depth, that are lockfiles or generated by a tool.
pub const GENERATED_NAMES: &[&str] = &[
    "package-lock.json",
    "npm-shrinkwrap.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
    "Cargo.lock",
    "poetry.lock",
    "uv.lock",
    "Pipfile.lock",
    "pdm.lock",
    "packages.lock.json",
    "go.sum",
    "Gemfile.lock",
    "composer.lock",
    "Podfile.lock",
    "pubspec.lock",
    "mix.lock",
    "flake.lock",
    "Package.resolved",
    "*.Designer.cs",
    "*.g.cs",
    "*.g.i.cs",
    "*.AssemblyAttributes.cs",
    "*ModelSnapshot.cs",
    "*.pb.go",
    "*_pb2.py",
    "*_pb2_grpc.py",
    "*.pb.cc",
    "*.pb.h",
    "*.min.js",
    "*.min.css",
    "*.map",
];

/// How much of a file [`has_generated_header`] reads: its first lines, but no more bytes than this.
pub const HEADER_BYTES: usize = 1024;
const HEADER_LINES: usize = 5;

/// Whether the first lines of a file say that a tool wrote it: `<auto-generated` (.NET),
/// `@generated`, or Go's `// Code generated … DO NOT EDIT.` line.
pub fn has_generated_header(content: &[u8]) -> bool {
    const GO_START: &[u8] = b"// Code generated ";
    const GO_END: &[u8] = b" DO NOT EDIT.";
    let head = &content[..content.len().min(HEADER_BYTES)];
    head.split(|&b| b == b'\n').take(HEADER_LINES).any(|line| {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        contains(line, b"<auto-generated")
            || contains(line, b"@generated")
            || line.strip_prefix(GO_START).is_some_and(|rest| rest.ends_with(GO_END))
    })
}

fn contains(haystack: &[u8], needle: &[u8]) -> bool {
    haystack.windows(needle.len()).any(|w| w == needle)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_markers_count_in_the_first_lines_only() {
        assert!(has_generated_header(b"// <auto-generated>\n// by a tool\n"));
        assert!(has_generated_header(b"# @generated by protoc\nimport x\n"));
        assert!(has_generated_header(
            b"// Code generated by protoc-gen-go. DO NOT EDIT.\r\npackage x\n"
        ));
        let late = b"a\nb\nc\nd\ne\n// @generated\n";
        assert!(!has_generated_header(late));
        let far = [vec![b'x'; HEADER_BYTES], b" @generated".to_vec()].concat();
        assert!(!has_generated_header(&far));
    }

    #[test]
    fn go_needs_its_whole_line() {
        assert!(!has_generated_header(b"// Code generated by hand, edit freely.\n"));
        assert!(!has_generated_header(b"x // Code generated by tool. DO NOT EDIT.\n"));
        assert!(!has_generated_header(
            b"// This is not generated. DO NOT EDIT. really\n"
        ));
    }
}
